(function(window, $) {
  if (!$) return;

  function getDraftMetaKey(form) {
    if (!form || !form.length) return "evalDraftMeta_scoresheet-form";
    var eid = String(form.find("[name=\"eid\"]").val() || "").trim();
    var judgeId = String(form.find("[name=\"evalJudgeInfo\"]").val() || "").trim();
    if (!eid || !judgeId) return "evalDraftMeta_scoresheet-form";
    return "evalDraftMeta_scoresheet-form_" + eid + "_" + judgeId;
  }

  function readDraftMeta(form) {
    try {
      var key = getDraftMetaKey(form);
      var raw = localStorage.getItem(key);
      if (!raw) return { key: key, saved_at: 0, dirty_at: 0 };
      var parsed = JSON.parse(raw);
      if (!parsed || typeof parsed !== "object") return { key: key, saved_at: 0, dirty_at: 0 };
      return {
        key: key,
        saved_at: parseInt(parsed.saved_at || 0, 10) || 0,
        dirty_at: parseInt(parsed.dirty_at || 0, 10) || 0
      };
    } catch (e) {
      return { key: getDraftMetaKey(form), saved_at: 0, dirty_at: 0 };
    }
  }

  function writeDraftMeta(form, patch) {
    try {
      var meta = readDraftMeta(form);
      if (patch && typeof patch === "object") {
        if (typeof patch.saved_at !== "undefined") meta.saved_at = parseInt(patch.saved_at || 0, 10) || 0;
        if (typeof patch.dirty_at !== "undefined") meta.dirty_at = parseInt(patch.dirty_at || 0, 10) || 0;
      }
      localStorage.setItem(meta.key, JSON.stringify({ saved_at: meta.saved_at, dirty_at: meta.dirty_at }));
      return meta;
    } catch (e) {
      return { key: getDraftMetaKey(form), saved_at: 0, dirty_at: 0 };
    }
  }

  window.getEvalLocalDraftMeta = function() {
    var form = $("#scoresheet-form");
    return readDraftMeta(form);
  };

  function setFieldValue($field, value) {
    if (!$field.length || typeof value === "undefined" || value === null) return;
    if ($field.is(":radio")) {
      $field.filter("[value=\"" + String(value).replace(/"/g, "\\\"") + "\"]").prop("checked", true);
      return;
    }
    if ($field.is(":checkbox")) {
      if (String(value) === "1" || value === 1 || value === true) $field.prop("checked", true);
      return;
    }
    $field.val(value);
  }

  function setByName(form, name, value) {
    setFieldValue(form.find("[name=\"" + name + "\"]"), value);
  }

  function setMultiByName(form, name, rawValue) {
    if (!rawValue) return;
    var values = String(rawValue).split(/\s*,\s*/);
    form.find("[name=\"" + name + "\"]").each(function() {
      if (values.indexOf($(this).val()) > -1) $(this).prop("checked", true);
    });
  }

  function setChecklistRadios(form, rawChecklist) {
    if (!rawChecklist) return;
    var values = String(rawChecklist).split(/\s*,\s*/);
    values.forEach(function(v) {
      form.find(":radio[value=\"" + v.replace(/"/g, "\\\"") + "\"]").prop("checked", true);
    });
  }

  function applyStructuredChecklist(form, rawJson) {
    if (!rawJson) return;
    var data;
    try { data = JSON.parse(rawJson); } catch (e) { data = null; }
    if (!data) return;
    Object.keys(data).forEach(function(key) {
      var value = data[key];
      var $field = form.find("[name=\"" + key + "\"]");
      if (!$field.length) return;
      if ($field.is(":checkbox")) {
        if (String(value) === "1") $field.prop("checked", true);
      } else {
        $field.val(value);
      }
    });
  }

  window.applyEvalDraftToForm = function(draft) {
    if (!draft) return;
    var form = $("#scoresheet-form");
    if (!form.length) return;

    setByName(form, "evalAromaScore", draft.evalAromaScore);
    setByName(form, "evalAppearanceScore", draft.evalAppearanceScore);
    setByName(form, "evalFlavorScore", draft.evalFlavorScore);
    setByName(form, "evalMouthfeelScore", draft.evalMouthfeelScore);
    setByName(form, "evalOverallScore", draft.evalOverallScore);
    setByName(form, "evalAromaComments", draft.evalAromaComments);
    setByName(form, "evalAppearanceComments", draft.evalAppearanceComments);
    setByName(form, "evalFlavorComments", draft.evalFlavorComments);
    setByName(form, "evalMouthfeelComments", draft.evalMouthfeelComments);
    setByName(form, "evalOverallComments", draft.evalOverallComments);
    setByName(form, "evalOtherNotes", draft.evalOtherNotes);
    setByName(form, "evalBottleNotes", draft.evalBottleNotes);
    setByName(form, "evalStyleAccuracy", draft.evalStyleAccuracy);
    setByName(form, "evalTechMerit", draft.evalTechMerit);
    setByName(form, "evalIntangibles", draft.evalIntangibles);
    setByName(form, "evalDrinkability", draft.evalDrinkability);
    setByName(form, "evalMiniBOS", draft.evalMiniBOS);
    if (String(draft.evalBottle) === "1") setByName(form, "evalBottle", "1");

    if (draft.evalPosition) {
      var parts = String(draft.evalPosition).split(",");
      if (parts.length > 0) setByName(form, "evalPosition_0", parts[0]);
      if (parts.length > 1) setByName(form, "evalPosition_1", parts[1]);
    }

    var formType = form.find("[name=\"evalFormType\"]").val();
    if (formType === "2") {
      setChecklistRadios(form, draft.evalAromaChecklist);
      setChecklistRadios(form, draft.evalAppearanceChecklist);
      setChecklistRadios(form, draft.evalFlavorChecklist);
      setChecklistRadios(form, draft.evalMouthfeelChecklist);
      setMultiByName(form, "evalAromaChecklistDesc[]", draft.evalAromaChecklistDesc);
      setMultiByName(form, "evalAppearanceChecklistDesc[]", draft.evalAppearanceChecklistDesc);
      setMultiByName(form, "evalFlavorChecklistDesc[]", draft.evalFlavorChecklistDesc);
      setMultiByName(form, "evalMouthfeelChecklistDesc[]", draft.evalMouthfeelChecklistDesc);
      setMultiByName(form, "evalOverallChecklistDesc[]", draft.evalOverallChecklistDesc);
      setMultiByName(form, "evalFlaws[]", draft.evalFlaws);
    }

    if ((formType === "3") || (formType === "4")) {
      applyStructuredChecklist(form, draft.evalAromaChecklist);
      applyStructuredChecklist(form, draft.evalAppearanceChecklist);
      applyStructuredChecklist(form, draft.evalFlavorChecklist);
      applyStructuredChecklist(form, draft.evalMouthfeelChecklist);
      setMultiByName(form, "evalFlaws[]", draft.evalFlaws);
    }

    form.find("input, textarea, select").trigger("change");
  };

  window.initEvalAutosave = function(config) {
    var form = $("#scoresheet-form");
    if (!form.length || !config || !config.endpoint) return;

    var dirty = false;
    var isSaving = false;
    var debounceTimer = null;
    var lastKeepAlive = 0;
    var $status = $("#eval-autosave-status");
    var $autosaveId = $("#evalAutosaveId");
    var savingByBeacon = false;

    function formatTime(ts) {
      var d = new Date(ts * 1000);
      var hh = d.getHours();
      var mm = String(d.getMinutes()).padStart(2, "0");
      var ampm = hh >= 12 ? "PM" : "AM";
      hh = hh % 12;
      if (hh === 0) hh = 12;
      return hh + ":" + mm + " " + ampm;
    }

    function extendClientTimer() {
      var now = Date.now();
      if (now - lastKeepAlive < (config.keepAliveThrottleMs || 60000)) return;
      lastKeepAlive = now;
      try {
        sessionStorage.setItem("lastTimeStamp", new Date().toString());
      } catch (e) {}
    }

    function doSave(sync) {
      if (!dirty || isSaving) return;
      isSaving = true;
      if ($status.length) $status.text(config.statusSaving || "Saving draft...");

      var autosaveId = $autosaveId.val() || 0;
      $.ajax({
        url: config.endpoint + "&id=" + encodeURIComponent(autosaveId),
        method: "POST",
        dataType: "json",
        data: form.serialize(),
        async: !sync
      }).done(function(resp) {
        if (resp && String(resp.status) === "1") {
          if (resp.id) $autosaveId.val(resp.id);
          dirty = false;
          if (resp.saved_at) writeDraftMeta(form, { saved_at: parseInt(resp.saved_at, 10) || 0, dirty_at: 0 });
          if ($status.length) {
            var label = config.statusSaved || "Draft saved at";
            var savedText = (resp.saved_at) ? formatTime(resp.saved_at) : "";
            $status.text(savedText ? (label + " " + savedText) : label);
          }
        } else if ($status.length) {
          $status.text(config.statusError || "Draft save failed. Keep working and submit when ready.");
        }
      }).fail(function() {
        if ($status.length) $status.text(config.statusError || "Draft save failed. Keep working and submit when ready.");
      }).always(function() {
        isSaving = false;
      });
    }

    function scheduleSave() {
      if (debounceTimer) window.clearTimeout(debounceTimer);
      debounceTimer = window.setTimeout(function() { doSave(false); }, config.autosaveDebounceMs || 3000);
    }

    form.on("input change", "input, textarea, select", function() {
      dirty = true;
      writeDraftMeta(form, { dirty_at: Math.floor(Date.now() / 1000) });
      extendClientTimer();
      scheduleSave();
    });

    window.setInterval(function() {
      if (dirty) doSave(false);
    }, config.autosaveIntervalMs || 30000);

    form.on("submit", function() {
      if (debounceTimer) window.clearTimeout(debounceTimer);
      doSave(true);
    });

    function doBeaconSave() {
      if (!dirty || isSaving || savingByBeacon) return;
      if (typeof navigator === "undefined" || typeof navigator.sendBeacon !== "function") return;
      savingByBeacon = true;
      try {
        var autosaveId = $autosaveId.val() || 0;
        var beaconUrl = config.endpoint + "&id=" + encodeURIComponent(autosaveId);
        var payload = new FormData(form[0]);
        var sent = navigator.sendBeacon(beaconUrl, payload);
        if (sent) {
          dirty = false;
          if ($status.length) $status.text(config.statusSaving || "Saving draft...");
        }
      } catch (e) {
      } finally {
        savingByBeacon = false;
      }
    }

    window.addEventListener("pagehide", doBeaconSave);
    window.addEventListener("beforeunload", doBeaconSave);
  };
})(window, window.jQuery);
